\begin{lemma}
\label{lemma-finite-type-field-Jacobson}
Toute algèbre de type fini sur un corps est de Jacobson.
\end{lemma}

\begin{proof}
Cela résulte du théorème \ref{theorem-nullstellensatz}
et de la définition \ref{definition-ring-jacobson}.
\end{proof}

